mapper.delete:
delete from CHB_BOT_AST_POS
where POS_DATE = #{batchTime,jdbcType=TIMESTAMP}
and DATASOURCE = '16'/*为避免误删除业务数据维护导入的数据，增加此条件*/

      begin

	     delete from CHB_BOT_AST_POS
	     where PLAN_ASSET_ID = #{item.posId,jdbcType=VARCHAR}  and POS_DATE = #{item.posDate,jdbcType=TIMESTAMP}
	     	and ASSET_CODE = #{item.assetCode,jdbcType=VARCHAR}

    ;end;

mapper.select:
SELECT SUB.VAL_DATE POS_DATE, SUB.PTL_ID PLAN_ASSET_ID, nvl(info.FINPROD_MARKET_ID,SUB.FINPROD_ID) ASSET_CODE, info2.REP_CCY CCY, NVL(SUM(decode(substr(sub.SUB_CODE,0,1),'2',0,sub.SECURITY_QUANTITY)),0)*DECODE(fp.TYPE_8,'F01',100,1) POS_NUM, case when fp.TYPE_8 in ('F16','F18','F19') and SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV)*-1,sub.SMV))<0 then 0 else nvl(SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV)*-1,sub.SMV)), 0) end as POS_AMT, nvl(SUM(CASE WHEN SUB.SUB_CODE LIKE '1204%' OR SUB.SUB_CODE LIKE '1203%' THEN SUB.SMV ELSE 0 END),0) INT_AMT,/** 利息**/ 0 SHADOW_AMT,/** 底层资产影子价格**/ ((case when fp.TYPE_8 in ('F16','F18','F19') and SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV)*-1,sub.SMV))<0 then 0 else nvl(SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV)*-1,sub.SMV)), 0) end) -nvl(SUM(CASE WHEN SUB.SUB_CODE LIKE '1204%' OR SUB.SUB_CODE LIKE '1203%' THEN SUB.SMV ELSE 0 END),0)) as POS_AMT_CPRICE,/** 底层资产折算人民币净价市值**/ case when fp.TYPE_8 in ('F16','F18','F19') and SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV_ORI)*-1,sub.SMV_ORI))<0 then 0 else nvl(SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV)*-1,sub.SMV_ORI)), 0) end as O_POS_AMT, /** 原币-底层资产全价币值（元）*/ nvl(SUM(CASE WHEN SUB.SUB_CODE LIKE '1204%' OR SUB.SUB_CODE LIKE '1203%' THEN SUB.SMV_ORI ELSE 0 END),0) as O_INT_AMT,/** 原币-利息**/ 0 as O_SHADOW_AMT,/** 原币-底层资产影子价格**/ ((case when fp.TYPE_8 in ('F16','F18','F19') and SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV_ORI)*-1,sub.SMV_ORI))<0 then 0 else nvl(SUM(decode(substr(sub.SUB_CODE,0,1),'2',ABS(sub.SMV_ORI)*-1,sub.SMV_ORI)), 0) end) -nvl(SUM(CASE WHEN SUB.SUB_CODE LIKE '1204%' OR SUB.SUB_CODE LIKE '1203%' THEN SUB.SMV_ORI ELSE 0 END),0)) as O_POS_AMT_CPRICE,/** 原币-底层资产净价市值**/ MAX(nvl(SUB.CREATE_TIME, SUB.UPDATE_TIME)) UPDATE_TIME FROM RSK_VALTBL_ASSET_SUB SUB /** 估值表导入后的资产数据**/
/** 估值表对应的资产科目类型，债券的数量需要乘以100**/ INNER JOIN RSK_VALTBL_PRT_BOTASSET_MAP DC ON SUB.PTL_ID = DC.PTL_ID AND SUB.SUB_CODE = DC.SUB_CODE AND SUB.FINPROD_ID = DC.FINPROD_ID /*获取底层资产的公开市场代码*/ LEFT JOIN REP_ASSET_DEPT info ON info.REP_FINPROD_ID = sub.FINPROD_ID /*判断是否为债券*/ LEFT JOIN fin_product_type fp ON fp.FINPROD_ID = sub.FINPROD_ID /*获取资管计划币种*/ LEFT JOIN REP_ASSET_DEPT info2 ON info2.FINPROD_MARKET_ID = sub.PTL_ID WHERE SUB.VAL_DATE = #{batchTime,jdbcType=DATE} AND SUB.FINPROD_ID IS NOT NULL AND DC.SUB_CLASS NOT IN ('ZHG', 'NHG') /** 过滤回购资产通过三级科目来计算**/ GROUP BY SUB.VAL_DATE, SUB.PTL_ID, nvl(info.FINPROD_MARKET_ID,SUB.FINPROD_ID), info2.REP_CCY,
fp.TYPE_8

select SUB.VAL_DATE POS_DATE,/** 持仓日期**/ SUB.PTL_ID PLAN_ASSET_ID,/** 资管计划行内资产/负债编码**/ SUB.SUB_CODE ASSET_CODE, /** 资产代码**/ fp.CCY CCY,/** 币种**/ SUM(IFNULL(SUB.SMV,0)) POS_AMT, SUM(IFNULL(SUB.SMV_ORI,0)) AS O_POS_AMT_CPRICE/**原币-底层资产全价币值（元）*/ FROM RSK_VALTBL_ASSET_SUB sub LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = sub.PTL_ID where SUB.VAL_DATE = #{batchTime,jdbcType=DATE}
#{subjectNo,jdbcType=VARCHAR}
group by SUB.VAL_DATE, SUB.PTL_ID, SUB.SUB_CODE, fp.CCY
